# skip-links.js — Adds skip-to-content navigation links

```js
/**
 * skip-links.js
 *
 * Adds "skip to content" navigation links at the top of a document so that
 * keyboard and screen reader users can bypass repeated blocks such as
 * headers and menus and move directly to the main regions of a page.
 *
 * Usage:
 *   import { initSkipLinks } from './skip-links.js';
 *   initSkipLinks({
 *     targets: [
 *       { selector: '#main', label: 'Skip to main content' },
 *       { selector: '#site-nav', label: 'Skip to navigation' }
 *     ]
 *   });
 */

const DEFAULTS = {
  containerClass: 'ui-skip-links',
  linkClass: 'ui-skip-link',
  visibleClass: 'ui-skip-link--visible',
  targets: [{ selector: 'main, [role="main"]', label: 'Skip to main content' }],
  insertAt: 'start'
};

let uniqueCounter = 0;

/**
 * Create a predictable id for elements that do not already have one.
 * @param {string} prefix
 * @returns {string}
 */
function generateId(prefix) {
  uniqueCounter += 1;
  return `${prefix}-${uniqueCounter}`;
}

/**
 * Ensure the target element can receive programmatic focus. Elements that
 * are not natively focusable get tabindex="-1" so focus can be moved to
 * them without adding them to the normal tab order.
 * @param {HTMLElement} el
 */
function makeFocusable(el) {
  if (!el.hasAttribute('tabindex')) {
    el.setAttribute('tabindex', '-1');
  }
}

/**
 * Move focus to the target and scroll it into view. The tabindex added
 * by makeFocusable is removed on blur so the page's tab order is unchanged.
 * @param {HTMLElement} el
 */
function focusTarget(el) {
  const addedTabindex = el.getAttribute('tabindex') === '-1';
  el.focus({ preventScroll: true });
  el.scrollIntoView({ block: 'start' });
  if (addedTabindex) {
    el.addEventListener('blur', function onBlur() {
      el.removeEventListener('blur', onBlur);
    });
  }
}

/**
 * Build a single skip link anchor element.
 * @param {HTMLElement} target
 * @param {string} label
 * @param {object} options
 * @returns {HTMLAnchorElement}
 */
function buildLink(target, label, options) {
  if (!target.id) {
    target.id = generateId('skip-target');
  }
  makeFocusable(target);

  const link = document.createElement('a');
  link.className = options.linkClass;
  link.href = `#${target.id}`;
  link.textContent = label;

  link.addEventListener('focus', () => link.classList.add(options.visibleClass));
  link.addEventListener('blur', () => link.classList.remove(options.visibleClass));

  link.addEventListener('click', (event) => {
    // Handle focus explicitly: some browsers scroll to the fragment
    // without moving keyboard focus to it.
    event.preventDefault();
    focusTarget(target);
    if (window.history && window.history.replaceState) {
      window.history.replaceState(null, '', `#${target.id}`);
    }
  });

  return link;
}

/**
 * Initialise skip links for the current document.
 * Targets that cannot be found on the page are ignored.
 *
 * @param {object} [userOptions]
 * @param {Array<{selector: string, label: string}>} [userOptions.targets]
 * @param {string} [userOptions.insertAt] 'start' or 'end' of document.body
 * @returns {{ destroy: Function, container: HTMLElement|null }}
 */
export function initSkipLinks(userOptions = {}) {
  const options = { ...DEFAULTS, ...userOptions };

  const container = document.createElement('nav');
  container.className = options.containerClass;
  container.setAttribute('aria-label', 'Skip links');

  const list = document.createElement('ul');
  list.style.listStyle = 'none';
  list.style.margin = '0';
  list.style.padding = '0';

  options.targets.forEach(({ selector, label }) => {
    const target = document.querySelector(selector);
    if (!target) return;
    const item = document.createElement('li');
    item.appendChild(buildLink(target, label, options));
    list.appendChild(item);
  });

  if (!list.children.length) {
    return { destroy() {}, container: null };
  }

  container.appendChild(list);

  if (options.insertAt === 'end') {
    document.body.appendChild(container);
  } else {
    document.body.insertBefore(container, document.body.firstChild);
  }

  return {
    container,
    destroy() {
      container.remove();
    }
  };
}
```

## Notes

The stylesheet should hide the links off-screen by default and reveal them when the `ui-skip-link--visible` class is applied. Avoid `display: none` and `visibility: hidden`, because both remove the links from the tab order and from the accessibility tree.

reduced-motion.js — Respects prefers-reduced-motion in animations and transitions

```js
/**
 * reduced-motion.js
 *
 * Central place for deciding whether the UI components may animate.
 * Modals, tabs, validation messages and other components call into this
 * module instead of reading the media query themselves, so behaviour stays
 * consistent and can be overridden by application code.
 *
 * Precedence, highest first:
 *   1. An explicit override set with setMotionPreference().
 *   2. The operating system setting exposed as prefers-reduced-motion.
 *   3. Motion allowed, when matchMedia is unavailable (e.g. server rendering).
 */

const QUERY = '(prefers-reduced-motion: reduce)';
const ATTRIBUTE = 'data-motion';

let mediaQueryList = null;
let override = null; // null = follow system, 'reduce' or 'allow' = forced
const listeners = new Set();

/** Lazily create the MediaQueryList so the module is safe to import anywhere. */
function getMediaQueryList() {
  if (mediaQueryList === null && typeof window !== 'undefined' && window.matchMedia) {
    mediaQueryList = window.matchMedia(QUERY);
    addChangeListener(mediaQueryList, handleSystemChange);
  }
  return mediaQueryList;
}

/** Older Safari versions only support addListener, so fall back to it. */
function addChangeListener(mql, handler) {
  if (typeof mql.addEventListener === 'function') {
    mql.addEventListener('change', handler);
  } else if (typeof mql.addListener === 'function') {
    mql.addListener(handler);
  }
}

function handleSystemChange() {
  if (override === null) {
    notify();
  }
}

function notify() {
  const reduced = prefersReducedMotion();
  syncDocument(reduced);
  listeners.forEach((listener) => {
    try {
      listener(reduced);
    } catch (error) {
      // A failing subscriber must not prevent the others from being notified.
      console.error('[reduced-motion] listener failed:', error);
    }
  });
}

/** Mirror the current state on <html> so CSS can target it. */
function syncDocument(reduced) {
  if (typeof document === 'undefined') return;
  document.documentElement.setAttribute(ATTRIBUTE, reduced ? 'reduce' : 'allow');
}

/**
 * Report whether animations should be reduced or skipped.
 * @returns {boolean}
 */
export function prefersReducedMotion() {
  if (override !== null) {
    return override === 'reduce';
  }
  const mql = getMediaQueryList();
  return mql ? mql.matches : false;
}

/**
 * Force a motion preference, for example from a user settings panel.
 * @param {'reduce'|'allow'|null} value  Pass null to follow the system again.
 */
export function setMotionPreference(value) {
  if (value !== null && value !== 'reduce' && value !== 'allow') {
    throw new TypeError(`Invalid motion preference: ${String(value)}`);
  }
  override = value;
  notify();
}

/**
 * Subscribe to preference changes.
 * @param {(reduced: boolean) => void} listener
 * @returns {() => void} Function that removes the subscription.
 */
export function onMotionPreferenceChange(listener) {
  getMediaQueryList();
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/**
 * Return the duration a component should use, in milliseconds.
 * When motion is reduced the duration is zero, so state changes are instant.
 * @param {number} ms  Duration to use when motion is allowed.
 * @returns {number}
 */
export function motionDuration(ms) {
  return prefersReducedMotion() ? 0 : ms;
}

/**
 * Animate an element with the Web Animations API, honouring the preference.
 * With reduced motion the final keyframe is applied immediately and the
 * returned promise still resolves, so callers can chain logic unchanged.
 *
 * @param {Element} element
 * @param {Keyframe[]} keyframes
 * @param {KeyframeAnimationOptions} [options]
 * @returns {Promise<void>}
 */
export function animate(element, keyframes, options = {}) {
  const canAnimate = typeof element.animate === 'function';
  if (prefersReducedMotion() || !canAnimate) {
    applyFinalFrame(element, keyframes);
    return Promise.resolve();
  }
  const animation = element.animate(keyframes, { fill: 'both', ...options });
  return animation.finished.then(() => {
    // Commit the end state so the animation object can be released.
    applyFinalFrame(element, keyframes);
    animation.cancel();
  });
}

function applyFinalFrame(element, keyframes) {
  const last = keyframes[keyframes.length - 1];
  if (!last) return;
  Object.keys(last).forEach((property) => {
    if (property === 'offset' || property === 'easing' || property === 'composite') return;
    element.style[property] = last[property];
  });
}

/**
 * Set a CSS transition on an element, or remove it when motion is reduced.
 * @param {HTMLElement} element
 * @param {string} property  CSS property name, e.g. "opacity".
 * @param {number} ms
 * @param {string} [easing]
 */
export function setTransition(element, property, ms, easing = 'ease') {
  const duration = motionDuration(ms);
  element.style.transition = duration === 0 ? 'none' : `${property} ${duration}ms ${easing}`;
}

// Establish the initial document state as soon as the module is loaded.
if (typeof document !== 'undefined') {
  syncDocument(prefersReducedMotion());
}
```

a11y-audit.js — Dev-time checks that warn about missing labels and roles

```js
/**
 * a11y-audit.js
 *
 * Development-only checks that inspect a DOM subtree and report common
 * accessibility problems: form controls without labels, dialogs without
 * accessible names, tabs without the expected ARIA relationships, and
 * interactive elements with no discernible text.
 *
 * The audit never modifies the DOM. In production builds, run() is a no-op.
 *
 * Usage:
 *   import { audit, registerRule } from './a11y-audit.js';
 *   audit(document.body);
 */

const isProduction = () =>
  typeof process !== 'undefined' &&
  process.env &&
  process.env.NODE_ENV === 'production';

const rules = [];
const reported = new WeakMap();

/**
 * Register a rule. Each rule has an id, a CSS selector that picks the
 * elements to inspect, and a check function that returns a message string
 * when the element has a problem, or null when it is acceptable.
 */
export function registerRule({ id, selector, check }) {
  rules.push({ id, selector, check });
}

/** Return the trimmed text content of an element, or an empty string. */
function textOf(el) {
  return (el.textContent || '').trim();
}

/** Resolve the ids listed in an attribute such as aria-labelledby. */
function referencedText(el, attr) {
  const ids = (el.getAttribute(attr) || '').split(/\s+/).filter(Boolean);
  return ids
    .map((id) => el.ownerDocument.getElementById(id))
    .filter(Boolean)
    .map(textOf)
    .join(' ')
    .trim();
}

/**
 * Compute a simplified accessible name. This covers the common sources
 * only: aria-labelledby, aria-label, associated <label>, title, and
 * element content. It is not a full accessible name computation.
 */
export function accessibleName(el) {
  const labelledBy = referencedText(el, 'aria-labelledby');
  if (labelledBy) return labelledBy;

  const ariaLabel = (el.getAttribute('aria-label') || '').trim();
  if (ariaLabel) return ariaLabel;

  if (el.labels && el.labels.length > 0) {
    const fromLabels = Array.from(el.labels).map(textOf).join(' ').trim();
    if (fromLabels) return fromLabels;
  }

  const title = (el.getAttribute('title') || '').trim();
  if (title) return title;

  return textOf(el);
}

registerRule({
  id: 'control-label',
  selector:
    'input:not([type="hidden"]):not([type="submit"]):not([type="button"]), select, textarea',
  check(el) {
    return accessibleName(el)
      ? null
      : 'Form control has no label. Add a <label for>, aria-label, or aria-labelledby.';
  },
});

registerRule({
  id: 'button-name',
  selector: 'button, [role="button"]',
  check(el) {
    return accessibleName(el)
      ? null
      : 'Button has no accessible text. Add visible text or an aria-label.';
  },
});

registerRule({
  id: 'dialog-name',
  selector: 'dialog, [role="dialog"], [role="alertdialog"]',
  check(el) {
    return accessibleName(el)
      ? null
      : 'Modal has no accessible name. Set aria-labelledby to the dialog heading.';
  },
});

registerRule({
  id: 'tab-controls',
  selector: '[role="tab"]',
  check(el) {
    const panelId = el.getAttribute('aria-controls');
    if (!panelId) return 'Tab is missing aria-controls.';
    if (!el.ownerDocument.getElementById(panelId)) {
      return `Tab references a missing panel with id "${panelId}".`;
    }
    return el.closest('[role="tablist"]')
      ? null
      : 'Tab is not inside an element with role="tablist".';
  },
});

registerRule({
  id: 'validation-live-region',
  selector: '[data-validation-message]',
  check(el) {
    const role = el.getAttribute('role');
    const live = el.getAttribute('aria-live');
    return role === 'alert' || live
      ? null
      : 'Validation message is not announced. Add role="alert" or aria-live.';
  },
});

/**
 * Run all rules against a root element. Each element/rule pair is reported
 * once per page session. Returns the list of findings for use in tests.
 */
export function audit(root = document) {
  if (isProduction() || !root || !root.querySelectorAll) return [];

  const findings = [];
  for (const rule of rules) {
    for (const el of root.querySelectorAll(rule.selector)) {
      const seen = reported.get(el) || new Set();
      if (seen.has(rule.id)) continue;

      const message = rule.check(el);
      if (!message) continue;

      seen.add(rule.id);
      reported.set(el, seen);
      findings.push({ rule: rule.id, element: el, message });
      console.warn(`[a11y-audit:${rule.id}] ${message}`, el);
    }
  }
  return findings;
}
```

event-bus.js — Lightweight pub/sub system for component communication

/**
 * event-bus.js
 *
 * A small publish/subscribe helper used by the form and UI components
 * (validation messages, modals, tabs, accessibility announcers) so they can
 * communicate without holding direct references to each other.
 *
 * Event names are plain strings. By convention they are namespaced with a
 * colon, for example "modal:open", "tabs:change" or "validation:error".
 * A listener registered for "*" receives every event.
 */

const WILDCARD = '*';

export class EventBus {
  /**
   * @param {Object} [options]
   * @param {Function} [options.onError] Called when a listener throws.
   *   Receives (error, eventName). Defaults to console.error.
   */
  constructor(options = {}) {
    this._listeners = new Map();
    this._onError = options.onError || ((error, eventName) => {
      console.error(`[EventBus] Listener for "${eventName}" failed:`, error);
    });
  }

  /**
   * Register a listener for an event.
   * @param {string} eventName
   * @param {Function} handler Receives (payload, eventName).
   * @returns {Function} A function that removes this registration.
   */
  on(eventName, handler) {
    assertEventName(eventName);
    assertHandler(handler);

    if (!this._listeners.has(eventName)) {
      this._listeners.set(eventName, []);
    }
    this._listeners.get(eventName).push({ handler, once: false });

    return () => this.off(eventName, handler);
  }

  /**
   * Register a listener that is removed after its first invocation.
   * @returns {Function} A function that removes this registration.
   */
  once(eventName, handler) {
    assertEventName(eventName);
    assertHandler(handler);

    if (!this._listeners.has(eventName)) {
      this._listeners.set(eventName, []);
    }
    this._listeners.get(eventName).push({ handler, once: true });

    return () => this.off(eventName, handler);
  }

  /**
   * Remove a previously registered listener. If no handler is given,
   * every listener for the event is removed.
   */
  off(eventName, handler) {
    const entries = this._listeners.get(eventName);
    if (!entries) return;

    if (!handler) {
      this._listeners.delete(eventName);
      return;
    }

    const remaining = entries.filter((entry) => entry.handler !== handler);
    if (remaining.length === 0) {
      this._listeners.delete(eventName);
    } else {
      this._listeners.set(eventName, remaining);
    }
  }

  /**
   * Publish an event to its listeners, then to wildcard listeners.
   * Listeners run synchronously in registration order. An error thrown by
   * one listener is reported through onError and does not stop the others.
   * @returns {number} How many listeners were invoked.
   */
  emit(eventName, payload) {
    assertEventName(eventName);

    const targeted = this._listeners.get(eventName) || [];
    const wildcard = eventName === WILDCARD ? [] : this._listeners.get(WILDCARD) || [];

    // Copy the lists so listeners may subscribe or unsubscribe while
    // an event is being dispatched.
    const queue = [...targeted, ...wildcard];

    for (const entry of queue) {
      if (entry.once) {
        this._removeEntry(entry);
      }
      try {
        entry.handler(payload, eventName);
      } catch (error) {
        this._onError(error, eventName);
      }
    }
    return queue.length;
  }

  /** Number of listeners registered for an event (wildcards not included). */
  listenerCount(eventName) {
    const entries = this._listeners.get(eventName);
    return entries ? entries.length : 0;
  }

  /** Remove every listener. Useful when tearing down a page or a test. */
  clear() {
    this._listeners.clear();
  }

  _removeEntry(target) {
    for (const [name, entries] of this._listeners) {
      const index = entries.indexOf(target);
      if (index !== -1) {
        const remaining = entries.filter((entry) => entry !== target);
        if (remaining.length === 0) {
          this._listeners.delete(name);
        } else {
          this._listeners.set(name, remaining);
        }
        return;
      }
    }
  }
}

function assertEventName(eventName) {
  if (typeof eventName !== 'string' || eventName === '') {
    throw new TypeError('Event name must be a non-empty string.');
  }
}

function assertHandler(handler) {
  if (typeof handler !== 'function') {
    throw new TypeError('Event handler must be a function.');
  }
}

/** Shared bus used by default across components on the same page. */
export const globalBus = new EventBus();

export default EventBus;

/*
 * Example usage:
 *
 *   import { globalBus } from './event-bus.js';
 *
 *   // A live region announces validation problems to screen readers.
 *   const stop = globalBus.on('validation:error', ({ field, message }) => {
 *     announce(`${field}: ${message}`);
 *   });
 *
 *   // A form component publishes the error.
 *   globalBus.emit('validation:error', { field: 'Email', message: 'Enter a valid address.' });
 *
 *   // Later, when the announcer is destroyed:
 *   stop();
 */

dom-utils.js — Small helpers for querying, creating, and toggling DOM elements

/**
 * dom-utils.js
 *
 * Small, dependency-free helpers used throughout the form and UI components
 * (validation messages, modals, tabs). Each helper wraps a native DOM call
 * and adds null-safety so that callers can chain operations without
 * checking for missing elements first.
 */

const FOCUSABLE_SELECTOR = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled]):not([type="hidden"])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])'
].join(',');

let idCounter = 0;

/**
 * Return the first element matching a selector, or null.
 * @param {string} selector - CSS selector.
 * @param {ParentNode} [root=document] - Node to search within.
 * @returns {Element|null}
 */
export function qs(selector, root = document) {
  return root.querySelector(selector);
}

/**
 * Return all elements matching a selector as a real array.
 * @param {string} selector - CSS selector.
 * @param {ParentNode} [root=document] - Node to search within.
 * @returns {Element[]}
 */
export function qsa(selector, root = document) {
  return Array.from(root.querySelectorAll(selector));
}

/**
 * Find the nearest ancestor (or the element itself) matching a selector.
 * Returns null when the element is missing or nothing matches.
 */
export function closest(el, selector) {
  return el ? el.closest(selector) : null;
}

/**
 * Create an element with attributes, classes, and children in one call.
 * @param {string} tag - Tag name, for example "div".
 * @param {Object} [options]
 * @param {Object} [options.attrs] - Attribute name/value pairs.
 * @param {string[]} [options.classes] - Class names to add.
 * @param {string} [options.text] - Text content (set safely, never as HTML).
 * @param {Array<Node|string>} [options.children] - Nodes or strings to append.
 * @returns {HTMLElement}
 */
export function create(tag, { attrs = {}, classes = [], text, children = [] } = {}) {
  const el = document.createElement(tag);
  setAttrs(el, attrs);
  classes.forEach((name) => el.classList.add(name));
  if (text !== undefined) {
    el.textContent = text;
  }
  children.forEach((child) => {
    el.append(child);
  });
  return el;
}

/**
 * Set several attributes at once. A value of null, undefined, or false
 * removes the attribute; true sets it as an empty boolean attribute.
 */
export function setAttrs(el, attrs) {
  if (!el) return el;
  Object.entries(attrs).forEach(([name, value]) => {
    if (value === null || value === undefined || value === false) {
      el.removeAttribute(name);
    } else {
      el.setAttribute(name, value === true ? '' : String(value));
    }
  });
  return el;
}

/**
 * Add or remove a class. When `force` is provided it decides the outcome;
 * otherwise the class is toggled.
 * @returns {boolean} True if the class is present afterwards.
 */
export function toggleClass(el, className, force) {
  if (!el) return false;
  return el.classList.toggle(className, force);
}

/**
 * Show or hide an element using the native `hidden` attribute, which
 * removes it from the accessibility tree as well as from layout.
 */
export function setHidden(el, hidden) {
  if (!el) return;
  el.hidden = Boolean(hidden);
}

export const show = (el) => setHidden(el, false);
export const hide = (el) => setHidden(el, true);

/**
 * Report whether an element is currently rendered. Elements with no
 * layout boxes (display: none, detached nodes) are treated as not visible.
 */
export function isVisible(el) {
  return Boolean(el && el.getClientRects().length > 0);
}

/**
 * List the focusable, visible descendants of a container in DOM order.
 * Used by the modal focus trap and by tab-list keyboard navigation.
 */
export function getFocusable(container) {
  return qsa(FOCUSABLE_SELECTOR, container).filter(isVisible);
}

/**
 * Generate a document-unique id, useful for linking labels, error
 * messages, and ARIA relationships (aria-describedby, aria-controls).
 * @param {string} [prefix="ui"]
 */
export function uniqueId(prefix = 'ui') {
  idCounter += 1;
  return `${prefix}-${idCounter}`;
}

/**
 * Attach a delegated event listener. The handler runs only when the event
 * target is inside an element matching `selector` within `root`.
 * @returns {Function} Call to remove the listener.
 */
export function delegate(root, eventName, selector, handler) {
  const listener = (event) => {
    const match = event.target.closest(selector);
    if (match && root.contains(match)) {
      handler.call(match, event, match);
    }
  };
  root.addEventListener(eventName, listener);
  return () => root.removeEventListener(eventName, listener);
}

/**
 * Remove all child nodes from an element.
 */
export function empty(el) {
  if (el) el.replaceChildren();
  return el;
}

/**
 * Run a callback once the DOM is ready, immediately if it already is.
 */
export function ready(callback) {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', callback, { once: true });
  } else {
    callback();
  }
}

positioning.js — Collision-aware placement calculations for floating elements

/**
 * positioning.js
 *
 * Calculates where a floating element (tooltip, popover, validation
 * message, dropdown) should be placed relative to an anchor element.
 * If the preferred side does not fit inside the viewport, the opposite
 * side is tried, and the result is clamped so the element stays visible.
 *
 * All coordinates are viewport coordinates, as returned by
 * getBoundingClientRect(). Callers using position: fixed can apply the
 * result directly; callers using position: absolute must add scroll offsets.
 */

export const PLACEMENTS = ['top', 'bottom', 'left', 'right'];

const OPPOSITE = {
  top: 'bottom',
  bottom: 'top',
  left: 'right',
  right: 'left',
};

const DEFAULTS = {
  placement: 'bottom',
  offset: 8,      // gap in pixels between anchor and floating element
  padding: 4,     // minimum distance in pixels from the viewport edge
  flip: true,     // try the opposite side when the preferred one overflows
};

/** Returns the visible area of the viewport as a rectangle-like object. */
function getViewportBounds() {
  const root = document.documentElement;
  return {
    top: 0,
    left: 0,
    right: root.clientWidth,
    bottom: root.clientHeight,
  };
}

/** Restricts value to the inclusive range between min and max. */
function clamp(value, min, max) {
  return Math.max(min, Math.min(value, max));
}

/**
 * Computes the top-left corner of the floating element for one placement,
 * centred on the anchor along the cross axis.
 */
function placeOnSide(anchor, size, placement, offset) {
  switch (placement) {
    case 'top':
      return {
        top: anchor.top - size.height - offset,
        left: anchor.left + anchor.width / 2 - size.width / 2,
      };
    case 'left':
      return {
        top: anchor.top + anchor.height / 2 - size.height / 2,
        left: anchor.left - size.width - offset,
      };
    case 'right':
      return {
        top: anchor.top + anchor.height / 2 - size.height / 2,
        left: anchor.right + offset,
      };
    case 'bottom':
    default:
      return {
        top: anchor.bottom + offset,
        left: anchor.left + anchor.width / 2 - size.width / 2,
      };
  }
}

/**
 * Returns how many pixels the floating element extends past the main-axis
 * edge it faces. A value of zero or less means the placement fits.
 */
function mainAxisOverflow(pos, size, placement, bounds, padding) {
  switch (placement) {
    case 'top':
      return bounds.top + padding - pos.top;
    case 'left':
      return bounds.left + padding - pos.left;
    case 'right':
      return pos.left + size.width - (bounds.right - padding);
    case 'bottom':
    default:
      return pos.top + size.height - (bounds.bottom - padding);
  }
}

/**
 * Computes the final position of a floating element.
 *
 * @param {Element} anchorEl    Element the floating element points to.
 * @param {Element} floatingEl  Element to be positioned; must be rendered
 *                              so that its size can be measured.
 * @param {Object}  [options]   See DEFAULTS for supported keys.
 * @returns {{top: number, left: number, placement: string}}
 */
export function computePosition(anchorEl, floatingEl, options = {}) {
  const { placement, offset, padding, flip } = { ...DEFAULTS, ...options };

  if (!PLACEMENTS.includes(placement)) {
    throw new RangeError(`Unknown placement "${placement}"`);
  }

  const anchor = anchorEl.getBoundingClientRect();
  const floating = floatingEl.getBoundingClientRect();
  const size = { width: floating.width, height: floating.height };
  const bounds = getViewportBounds();

  let finalPlacement = placement;
  let pos = placeOnSide(anchor, size, placement, offset);

  if (flip && mainAxisOverflow(pos, size, placement, bounds, padding) > 0) {
    const alternate = OPPOSITE[placement];
    const altPos = placeOnSide(anchor, size, alternate, offset);
    const original = mainAxisOverflow(pos, size, placement, bounds, padding);
    const flipped = mainAxisOverflow(altPos, size, alternate, bounds, padding);

    // Only switch sides when the alternate side overflows less.
    if (flipped < original) {
      finalPlacement = alternate;
      pos = altPos;
    }
  }

  // Keep the element inside the viewport along both axes.
  const maxLeft = bounds.right - padding - size.width;
  const maxTop = bounds.bottom - padding - size.height;

  return {
    top: clamp(pos.top, bounds.top + padding, Math.max(maxTop, padding)),
    left: clamp(pos.left, bounds.left + padding, Math.max(maxLeft, padding)),
    placement: finalPlacement,
  };
}

/**
 * Applies a computed position to the floating element and records the
 * resolved placement in a data attribute so CSS can style arrows.
 */
export function applyPosition(floatingEl, position) {
  floatingEl.style.position = 'fixed';
  floatingEl.style.top = `${position.top}px`;
  floatingEl.style.left = `${position.left}px`;
  floatingEl.dataset.placement = position.placement;
}

/**
 * Keeps a floating element positioned while the page scrolls or resizes.
 * Returns a function that removes the listeners.
 */
export function autoUpdate(anchorEl, floatingEl, options = {}) {
  let frame = null;

  const update = () => {
    if (frame !== null) return;
    frame = requestAnimationFrame(() => {
      frame = null;
      applyPosition(floatingEl, computePosition(anchorEl, floatingEl, options));
    });
  };

  window.addEventListener('scroll', update, true);
  window.addEventListener('resize', update);
  update();

  return () => {
    if (frame !== null) cancelAnimationFrame(frame);
    window.removeEventListener('scroll', update, true);
    window.removeEventListener('resize', update);
  };
}

i18n.js — Localization layer for messages, dates, and numbers

```js
/**
 * i18n.js
 *
 * Localization layer shared by validation messages, modals, tabs and
 * other components. It provides:
 *   - message catalogs with fallback locales and placeholder interpolation
 *   - plural-aware messages built on Intl.PluralRules
 *   - cached date and number formatters built on Intl
 *   - text direction detection so components can set dir and aria attributes
 *
 * Catalogs are plain objects keyed by message id. A message is either a
 * string or an object of plural categories ("one", "other", ...).
 */

const DEFAULT_LOCALE = 'en';
const RTL_LANGUAGES = new Set(['ar', 'he', 'fa', 'ur']);

const catalogs = new Map();      // locale -> { messageId: message }
const formatterCache = new Map(); // cache key -> Intl formatter
const listeners = new Set();

let activeLocale = DEFAULT_LOCALE;
let fallbackLocale = DEFAULT_LOCALE;

/** Merge messages into the catalog for a locale. Existing ids are replaced. */
export function registerMessages(locale, messages) {
  const existing = catalogs.get(locale) || {};
  catalogs.set(locale, Object.assign({}, existing, messages));
}

/** Return the active locale tag, for example "fr-CA". */
export function getLocale() {
  return activeLocale;
}

/** Set the locale used when a message is missing from the active locale. */
export function setFallbackLocale(locale) {
  fallbackLocale = locale;
}

/**
 * Change the active locale and notify subscribers.
 * Unsupported tags are rejected so the UI never ends up in a half-translated state.
 */
export function setLocale(locale) {
  if (!Intl.DateTimeFormat.supportedLocalesOf([locale]).length) {
    throw new RangeError('Unsupported locale: ' + locale);
  }
  activeLocale = locale;
  formatterCache.clear();
  document.documentElement.lang = locale;
  document.documentElement.dir = getDirection(locale);
  listeners.forEach((callback) => callback(locale));
}

/** Subscribe to locale changes. Returns a function that removes the subscription. */
export function onLocaleChange(callback) {
  listeners.add(callback);
  return () => listeners.delete(callback);
}

/** Return "rtl" or "ltr" for a locale tag based on its language subtag. */
export function getDirection(locale = activeLocale) {
  const language = locale.split('-')[0].toLowerCase();
  return RTL_LANGUAGES.has(language) ? 'rtl' : 'ltr';
}

/**
 * Candidate locales to search, from most to least specific.
 * "fr-CA" yields ["fr-CA", "fr", <fallback>].
 */
function lookupChain(locale) {
  const chain = [locale];
  const language = locale.split('-')[0];
  if (language !== locale) chain.push(language);
  if (!chain.includes(fallbackLocale)) chain.push(fallbackLocale);
  return chain;
}

function findMessage(id, locale) {
  for (const candidate of lookupChain(locale)) {
    const catalog = catalogs.get(candidate);
    if (catalog && Object.prototype.hasOwnProperty.call(catalog, id)) {
      return catalog[id];
    }
  }
  return undefined;
}

/** Replace {name} placeholders with values. Unknown placeholders are left intact. */
function interpolate(template, values) {
  return template.replace(/\{(\w+)\}/g, (match, key) =>
    key in values ? String(values[key]) : match
  );
}

/**
 * Translate a message id.
 *
 *   t('form.required')
 *   t('form.minLength', { count: 8 })
 *
 * When the message is an object, the plural category for values.count is
 * selected, falling back to "other". Missing ids return the id itself so
 * the gap is visible during development.
 */
export function t(id, values = {}) {
  const message = findMessage(id, activeLocale);
  if (message === undefined) return id;
  if (typeof message === 'string') return interpolate(message, values);

  const category = new Intl.PluralRules(activeLocale).select(Number(values.count));
  const template = message[category] || message.other || id;
  return interpolate(template, values);
}

function getFormatter(Constructor, options) {
  const key = Constructor.name + '|' + activeLocale + '|' + JSON.stringify(options || {});
  if (!formatterCache.has(key)) {
    formatterCache.set(key, new Constructor(activeLocale, options));
  }
  return formatterCache.get(key);
}

/** Format a number, for example formatNumber(1234.5, { style: 'currency', currency: 'EUR' }). */
export function formatNumber(value, options) {
  return getFormatter(Intl.NumberFormat, options).format(value);
}

/** Format a Date, timestamp or ISO string. Invalid input returns an empty string. */
export function formatDate(value, options = { dateStyle: 'medium' }) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return getFormatter(Intl.DateTimeFormat, options).format(date);
}

/**
 * Translate static markup. Elements with data-i18n receive their text content;
 * data-i18n-attr="aria-label:modal.close" sets translated attributes.
 */
export function translateDocument(root = document) {
  root.querySelectorAll('[data-i18n]').forEach((el) => {
    el.textContent = t(el.dataset.i18n);
  });
  root.querySelectorAll('[data-i18n-attr]').forEach((el) => {
    el.dataset.i18nAttr.split(';').forEach((pair) => {
      const [attribute, id] = pair.split(':');
      if (attribute && id) el.setAttribute(attribute.trim(), t(id.trim()));
    });
  });
}
```

theme.js — CSS custom property tokens and theme switching

```js
/**
 * theme.js
 *
 * Defines design tokens as CSS custom properties and provides helpers for
 * switching between named themes. Components never hard-code colours; they
 * read values such as var(--ui-color-surface) from the document root.
 *
 * Public API:
 *   registerTheme(name, tokens)  add or replace a theme
 *   applyTheme(name, options)    activate a theme and persist the choice
 *   getTheme()                   name of the active theme
 *   initTheme()                  choose a starting theme on page load
 *   onThemeChange(fn)            subscribe; returns an unsubscribe function
 */

const STORAGE_KEY = 'ui-theme';
const TOKEN_PREFIX = '--ui-';
const DEFAULT_THEME = 'light';

/** Token sets keyed by theme name. Keys omit the shared prefix. */
const themes = {
  light: {
    'color-surface': '#ffffff',
    'color-surface-raised': '#f6f7f9',
    'color-text': '#1b1f24',
    'color-text-muted': '#4a5360',
    'color-border': '#c5cbd3',
    'color-accent': '#0b5fff',
    'color-error': '#b3261e',
    'color-success': '#1e7a3c',
    'color-focus-ring': '#0b5fff',
    'color-overlay': 'rgba(0, 0, 0, 0.5)',
  },
  dark: {
    'color-surface': '#14171c',
    'color-surface-raised': '#1e232b',
    'color-text': '#eef0f3',
    'color-text-muted': '#aab2be',
    'color-border': '#3a424d',
    'color-accent': '#7aa7ff',
    'color-error': '#ff8a80',
    'color-success': '#6fd08c',
    'color-focus-ring': '#a8c4ff',
    'color-overlay': 'rgba(0, 0, 0, 0.7)',
  },
};

const listeners = new Set();
let activeTheme = null;

/**
 * Register a theme. Missing tokens fall back to the default theme so a
 * partial theme never leaves a component without a colour.
 */
export function registerTheme(name, tokens) {
  if (typeof name !== 'string' || !name) {
    throw new TypeError('Theme name must be a non-empty string.');
  }
  themes[name] = { ...themes[DEFAULT_THEME], ...tokens };
}

/** Return the name of the active theme, or null before initialisation. */
export function getTheme() {
  return activeTheme;
}

/**
 * Activate a theme by writing its tokens onto the root element.
 *
 * @param {string} name - A registered theme name.
 * @param {{persist?: boolean, root?: HTMLElement}} [options]
 *   persist: store the choice in localStorage (default true).
 *   root: element that receives the properties (default <html>).
 */
export function applyTheme(name, options = {}) {
  const { persist = true, root = document.documentElement } = options;
  const tokens = themes[name];

  if (!tokens) {
    throw new Error(`Unknown theme "${name}".`);
  }
  if (name === activeTheme && root === document.documentElement) {
    return;
  }

  for (const [key, value] of Object.entries(tokens)) {
    root.style.setProperty(TOKEN_PREFIX + key, value);
  }

  // The attribute lets stylesheets target a theme directly if needed, and
  // color-scheme keeps native controls and scrollbars consistent.
  root.setAttribute('data-ui-theme', name);
  root.style.colorScheme = name === 'dark' ? 'dark' : 'light';

  const previous = activeTheme;
  activeTheme = name;

  if (persist) {
    try {
      localStorage.setItem(STORAGE_KEY, name);
    } catch (err) {
      // Storage can be unavailable in private mode; the theme still applies.
    }
  }

  listeners.forEach((fn) => fn(name, previous));
}

/** Read a previously saved theme name, ignoring names no longer registered. */
function readStoredTheme() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored && themes[stored] ? stored : null;
  } catch (err) {
    return null;
  }
}

/**
 * Pick a starting theme: saved choice first, then the operating system
 * preference, then the default. Without a saved choice, the theme follows
 * later changes to the system preference.
 */
export function initTheme() {
  const query = window.matchMedia('(prefers-color-scheme: dark)');
  const stored = readStoredTheme();

  applyTheme(stored || (query.matches ? 'dark' : DEFAULT_THEME), {
    persist: false,
  });

  query.addEventListener('change', (event) => {
    if (!readStoredTheme()) {
      applyTheme(event.matches ? 'dark' : DEFAULT_THEME, { persist: false });
    }
  });
}

/**
 * Subscribe to theme changes. The callback receives the new and previous
 * theme names. Call the returned function to unsubscribe.
 */
export function onThemeChange(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}
```

Notes on usage: call `initTheme()` once, as early as possible, to reduce a flash of the wrong theme. Components that draw to a canvas or compute colours in script can use `onThemeChange` and then read values with `getComputedStyle(document.documentElement).getPropertyValue('--ui-color-text')`.

cli/commands/import_.py — Handler for importing notes from external files

```python
"""Import command: load notes from JSON, Markdown, or plain-text files.

Usage examples:
    notes import backup.json
    notes import ~/journal --format markdown --tag journal
    notes import todo.txt --dry-run

Markdown files may start with a simple front-matter block delimited by
lines containing only "---". Recognised keys are "title" and "tags"
(a comma-separated list).
"""

import argparse
import json
import sqlite3
import sys
from pathlib import Path

from notes.db import connect, insert_note, attach_tag, note_exists
from notes.errors import ImportFormatError

SUPPORTED_FORMATS = ("json", "markdown", "text")
MARKDOWN_SUFFIXES = {".md", ".markdown"}


def register(subparsers):
    """Attach the 'import' sub-command to the main argument parser."""
    parser = subparsers.add_parser(
        "import", help="import notes from external files"
    )
    parser.add_argument("path", type=Path, help="file or directory to import")
    parser.add_argument(
        "--format", choices=SUPPORTED_FORMATS, default=None,
        help="input format (guessed from the file suffix when omitted)",
    )
    parser.add_argument(
        "--tag", action="append", default=[],
        help="tag to add to every imported note (may be repeated)",
    )
    parser.add_argument(
        "--skip-duplicates", action="store_true",
        help="skip notes whose title and body already exist",
    )
    parser.add_argument(
        "--dry-run", action="store_true",
        help="parse the input and report results without writing",
    )
    parser.set_defaults(handler=run)


def guess_format(path):
    """Return the format name implied by a file's suffix."""
    suffix = path.suffix.lower()
    if suffix == ".json":
        return "json"
    if suffix in MARKDOWN_SUFFIXES:
        return "markdown"
    return "text"


def parse_json(path):
    """Yield note dicts from a JSON file holding a list of objects."""
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, list):
        raise ImportFormatError(f"{path}: expected a top-level list")
    for item in data:
        if not isinstance(item, dict) or "body" not in item:
            raise ImportFormatError(f"{path}: entry without a 'body' field")
        yield {
            "title": item.get("title") or path.stem,
            "body": item["body"],
            "tags": list(item.get("tags", [])),
        }


def parse_markdown(path):
    """Yield one note from a Markdown file, reading optional front matter."""
    lines = path.read_text(encoding="utf-8").splitlines()
    meta = {}
    if lines and lines[0].strip() == "---":
        for index, line in enumerate(lines[1:], start=1):
            if line.strip() == "---":
                lines = lines[index + 1:]
                break
            key, _, value = line.partition(":")
            meta[key.strip().lower()] = value.strip()
    tags = [t.strip() for t in meta.get("tags", "").split(",") if t.strip()]
    yield {
        "title": meta.get("title") or path.stem,
        "body": "\n".join(lines).strip(),
        "tags": tags,
    }


def parse_text(path):
    """Yield one note per file, using the file name as the title."""
    yield {
        "title": path.stem,
        "body": path.read_text(encoding="utf-8").strip(),
        "tags": [],
    }


PARSERS = {"json": parse_json, "markdown": parse_markdown, "text": parse_text}


def collect_files(path):
    """Return the files to import: the path itself or a directory's files."""
    if path.is_dir():
        return sorted(p for p in path.iterdir() if p.is_file())
    return [path]


def run(args):
    """Execute the import and return a process exit code."""
    if not args.path.exists():
        print(f"error: {args.path} does not exist", file=sys.stderr)
        return 2

    imported = skipped = failed = 0
    conn = connect()
    try:
        for file_path in collect_files(args.path):
            fmt = args.format or guess_format(file_path)
            try:
                notes = list(PARSERS[fmt](file_path))
            except (ImportFormatError, ValueError, OSError) as exc:
                print(f"warning: {file_path}: {exc}", file=sys.stderr)
                failed += 1
                continue

            for note in notes:
                if args.skip_duplicates and note_exists(
                    conn, note["title"], note["body"]
                ):
                    skipped += 1
                    continue
                if not args.dry_run:
                    note_id = insert_note(conn, note["title"], note["body"])
                    for tag in note["tags"] + args.tag:
                        attach_tag(conn, note_id, tag)
                imported += 1
        if args.dry_run:
            conn.rollback()
        else:
            conn.commit()
    except sqlite3.Error as exc:
        conn.rollback()
        print(f"database error: {exc}", file=sys.stderr)
        return 1
    finally:
        conn.close()

    label = "would import" if args.dry_run else "imported"
    print(f"{label}: {imported}, skipped: {skipped}, failed files: {failed}")
    return 0 if failed == 0 else 1
```

db/fts.py — Sets up and maintains the FTS5 virtual table and triggers

```python
"""Full-text search support for the notes database.

The index lives in an FTS5 virtual table named ``notes_fts``. Its rowid
always equals ``notes.id``, and it carries three searchable columns:
title, body, and a space-separated list of tag names. Triggers keep the
index in step with the ``notes``, ``note_tags`` and ``tags`` tables, so
the rest of the application never has to write to it directly.
"""

import sqlite3

FTS_TABLE = "notes_fts"

# Subquery that builds the tag text for one note. ``{ref}`` is replaced
# with the SQL expression that yields the note id (for example new.note_id).
_TAG_TEXT = """(
    SELECT coalesce(group_concat(t.name, ' '), '')
    FROM note_tags AS nt
    JOIN tags AS t ON t.id = nt.tag_id
    WHERE nt.note_id = {ref}
)"""

_TRIGGER_NAMES = (
    "notes_fts_ai",
    "notes_fts_ad",
    "notes_fts_au",
    "note_tags_fts_ai",
    "note_tags_fts_ad",
    "tags_fts_au",
)


def fts5_available(conn: sqlite3.Connection) -> bool:
    """Return True if this SQLite build was compiled with FTS5."""
    rows = conn.execute("PRAGMA compile_options").fetchall()
    return any(row[0] == "ENABLE_FTS5" for row in rows)


def _table_exists(conn: sqlite3.Connection, name: str) -> bool:
    row = conn.execute(
        "SELECT 1 FROM sqlite_master WHERE name = ?", (name,)
    ).fetchone()
    return row is not None


def _create_triggers(conn: sqlite3.Connection) -> None:
    """Create the triggers that mirror data changes into the index."""
    new_tags = _TAG_TEXT.format(ref="new.note_id")
    old_tags = _TAG_TEXT.format(ref="old.note_id")
    renamed = _TAG_TEXT.format(ref="notes_fts.rowid")

    conn.executescript(f"""
    CREATE TRIGGER IF NOT EXISTS notes_fts_ai AFTER INSERT ON notes
    BEGIN
        INSERT INTO {FTS_TABLE}(rowid, title, body, tags)
        VALUES (new.id, new.title, new.body, '');
    END;

    CREATE TRIGGER IF NOT EXISTS notes_fts_ad AFTER DELETE ON notes
    BEGIN
        DELETE FROM {FTS_TABLE} WHERE rowid = old.id;
    END;

    CREATE TRIGGER IF NOT EXISTS notes_fts_au
    AFTER UPDATE OF title, body ON notes
    BEGIN
        UPDATE {FTS_TABLE}
        SET title = new.title, body = new.body
        WHERE rowid = new.id;
    END;

    CREATE TRIGGER IF NOT EXISTS note_tags_fts_ai AFTER INSERT ON note_tags
    BEGIN
        UPDATE {FTS_TABLE} SET tags = {new_tags}
        WHERE rowid = new.note_id;
    END;

    CREATE TRIGGER IF NOT EXISTS note_tags_fts_ad AFTER DELETE ON note_tags
    BEGIN
        UPDATE {FTS_TABLE} SET tags = {old_tags}
        WHERE rowid = old.note_id;
    END;

    CREATE TRIGGER IF NOT EXISTS tags_fts_au AFTER UPDATE OF name ON tags
    BEGIN
        UPDATE {FTS_TABLE} SET tags = {renamed}
        WHERE rowid IN (
            SELECT note_id FROM note_tags WHERE tag_id = new.id
        );
    END;
    """)


def rebuild_index(conn: sqlite3.Connection) -> None:
    """Discard the index contents and repopulate them from the base tables."""
    tags = _TAG_TEXT.format(ref="n.id")
    with conn:
        conn.execute(f"DELETE FROM {FTS_TABLE}")
        conn.execute(
            f"""INSERT INTO {FTS_TABLE}(rowid, title, body, tags)
                SELECT n.id, n.title, n.body, {tags} FROM notes AS n"""
        )


def ensure_fts(conn: sqlite3.Connection) -> None:
    """Create the FTS table and triggers if missing; safe to call repeatedly.

    A newly created table is populated from existing notes, so databases
    that predate full-text search are upgraded transparently.
    """
    if not fts5_available(conn):
        raise RuntimeError("This SQLite build does not include FTS5 support.")

    created = not _table_exists(conn, FTS_TABLE)
    with conn:
        conn.execute(
            f"""CREATE VIRTUAL TABLE IF NOT EXISTS {FTS_TABLE} USING fts5(
                    title, body, tags,
                    tokenize = 'porter unicode61 remove_diacritics 2'
                )"""
        )
        _create_triggers(conn)
    if created:
        rebuild_index(conn)


def drop_fts(conn: sqlite3.Connection) -> None:
    """Remove the triggers and the FTS table (used by migrations and tests)."""
    with conn:
        for name in _TRIGGER_NAMES:
            conn.execute(f"DROP TRIGGER IF EXISTS {name}")
        conn.execute(f"DROP TABLE IF EXISTS {FTS_TABLE}")


def optimize_index(conn: sqlite3.Connection) -> None:
    """Merge the index's internal segments to keep queries fast."""
    with conn:
        conn.execute(f"INSERT INTO {FTS_TABLE}({FTS_TABLE}) VALUES ('optimize')")


def index_is_consistent(conn: sqlite3.Connection) -> bool:
    """Return True if every note has exactly one row in the index."""
    notes = conn.execute("SELECT count(*) FROM notes").fetchone()[0]
    indexed = conn.execute(f"SELECT count(*) FROM {FTS_TABLE}").fetchone()[0]
    return notes == indexed
```

models/note.py — Note dataclass with validation and serialization helpers

```python
"""Note model for the personal notes database.

A Note is a plain value object. It validates its own fields on creation and
knows how to convert itself to and from dictionaries, JSON, and SQLite rows.
It does not open database connections; persistence lives in the storage layer.
"""
from __future__ import annotations

import json
import re
import sqlite3
from dataclasses import dataclass, field, replace
from datetime import datetime, timezone
from typing import Any, Iterable, Optional

MAX_TITLE_LENGTH = 200
MAX_BODY_LENGTH = 100000
MAX_TAG_LENGTH = 40

# Tags are lowercase, start with a letter or digit, and may contain
# digits, underscores and hyphens afterwards.
_TAG_PATTERN = re.compile(r"^[a-z0-9][a-z0-9_-]*$")


class NoteValidationError(ValueError):
    """Raised when a note field fails validation."""


def utc_now() -> datetime:
    """Return the current time as a timezone-aware UTC datetime."""
    return datetime.now(timezone.utc)


def normalize_tag(raw: str) -> str:
    """Return the canonical form of a tag or raise NoteValidationError."""
    tag = raw.strip().lower().replace(" ", "-")
    if not tag:
        raise NoteValidationError("tag must not be empty")
    if len(tag) > MAX_TAG_LENGTH:
        raise NoteValidationError(
            f"tag exceeds {MAX_TAG_LENGTH} characters: {tag[:MAX_TAG_LENGTH]}..."
        )
    if not _TAG_PATTERN.match(tag):
        raise NoteValidationError(f"invalid tag: {raw!r}")
    return tag


def _parse_timestamp(value: Any, field_name: str) -> datetime:
    """Accept a datetime or an ISO 8601 string and return an aware datetime."""
    if isinstance(value, str):
        try:
            value = datetime.fromisoformat(value)
        except ValueError as exc:
            raise NoteValidationError(f"{field_name} is not ISO 8601: {value!r}") from exc
    if not isinstance(value, datetime):
        raise NoteValidationError(f"{field_name} must be a datetime or string")
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value


@dataclass
class Note:
    """A single note with a title, free-form body, and a set of tags."""

    title: str
    body: str = ""
    tags: list[str] = field(default_factory=list)
    id: Optional[int] = None
    created_at: datetime = field(default_factory=utc_now)
    updated_at: datetime = field(default_factory=utc_now)

    def __post_init__(self) -> None:
        self.title = self.title.strip()
        if not self.title:
            raise NoteValidationError("title must not be empty")
        if len(self.title) > MAX_TITLE_LENGTH:
            raise NoteValidationError(f"title exceeds {MAX_TITLE_LENGTH} characters")
        if len(self.body) > MAX_BODY_LENGTH:
            raise NoteValidationError(f"body exceeds {MAX_BODY_LENGTH} characters")
        self.tags = self._clean_tags(self.tags)
        self.created_at = _parse_timestamp(self.created_at, "created_at")
        self.updated_at = _parse_timestamp(self.updated_at, "updated_at")

    @staticmethod
    def _clean_tags(tags: Iterable[str]) -> list[str]:
        """Normalize tags, drop duplicates, and keep them sorted."""
        return sorted({normalize_tag(t) for t in tags})

    # -- mutation helpers (return new objects; the original is untouched) --

    def with_tags(self, *new_tags: str) -> "Note":
        """Return a copy with the given tags added."""
        return replace(self, tags=self._clean_tags([*self.tags, *new_tags]))

    def without_tags(self, *old_tags: str) -> "Note":
        """Return a copy with the given tags removed, if present."""
        drop = {normalize_tag(t) for t in old_tags}
        return replace(self, tags=[t for t in self.tags if t not in drop])

    def touched(self) -> "Note":
        """Return a copy whose updated_at is set to the current time."""
        return replace(self, updated_at=utc_now())

    # -- serialization --

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-friendly dictionary."""
        return {
            "id": self.id,
            "title": self.title,
            "body": self.body,
            "tags": list(self.tags),
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> "Note":
        """Build a Note from a dictionary such as one produced by to_dict."""
        if "title" not in data:
            raise NoteValidationError("missing required field: title")
        kwargs: dict[str, Any] = {
            "title": data["title"],
            "body": data.get("body", ""),
            "tags": data.get("tags", []),
            "id": data.get("id"),
        }
        for name in ("created_at", "updated_at"):
            if data.get(name) is not None:
                kwargs[name] = data[name]
        return cls(**kwargs)

    def to_json(self, indent: Optional[int] = None) -> str:
        """Serialize the note to a JSON string."""
        return json.dumps(self.to_dict(), indent=indent, ensure_ascii=False)

    @classmethod
    def from_json(cls, text: str) -> "Note":
        """Parse a JSON string into a Note."""
        try:
            data = json.loads(text)
        except json.JSONDecodeError as exc:
            raise NoteValidationError(f"invalid JSON: {exc.msg}") from exc
        if not isinstance(data, dict):
            raise NoteValidationError("JSON document must be an object")
        return cls.from_dict(data)

    @classmethod
    def from_row(cls, row: sqlite3.Row, tags: Iterable[str] = ()) -> "Note":
        """Build a Note from a row of the notes table plus its tags."""
        return cls(
            id=row["id"],
            title=row["title"],
            body=row["body"],
            tags=list(tags),
            created_at=row["created_at"],
            updated_at=row["updated_at"],
        )

    def to_row(self) -> dict[str, Any]:
        """Return column values for INSERT or UPDATE; tags are stored separately."""
        return {
            "title": self.title,
            "body": self.body,
            "created_at": self.created_at.isoformat(),
            "updated_at": self.updated_at.isoformat(),
        }
