models/tag.py — Tag dataclass and name normalization rules

```python
"""Tag model and name normalization rules for the notes database.

Every tag name that reaches storage passes through ``normalize_tag_name``.
This keeps lookups exact: the database never holds two tags that differ
only by case, surrounding whitespace, or a leading "#".

Normalization rules:
  * Unicode text is converted to NFKC form.
  * Surrounding whitespace and a single leading "#" are removed.
  * Letters are lowercased.
  * Runs of internal whitespace become a single hyphen.
  * "/" separates hierarchy levels, e.g. "projects/website".
  * Empty hierarchy levels (from "a//b" or a trailing "/") are dropped.
  * Each level may contain only a-z, 0-9, "_" and "-", and must begin
    with a letter or digit.
  * The complete name may not exceed MAX_TAG_LENGTH characters.
"""
from __future__ import annotations

import re
import sqlite3
import unicodedata
from dataclasses import dataclass
from typing import Iterable, Optional

MAX_TAG_LENGTH = 64
HIERARCHY_SEPARATOR = "/"

_WHITESPACE_RUN = re.compile(r"\s+")
_VALID_SEGMENT = re.compile(r"^[a-z0-9][a-z0-9_-]*$")


class InvalidTagError(ValueError):
    """Raised when a tag name cannot be normalized into a valid name."""


def normalize_tag_name(raw: str) -> str:
    """Return the canonical form of ``raw`` or raise InvalidTagError."""
    if not isinstance(raw, str):
        raise InvalidTagError(f"tag name must be a string, got {type(raw).__name__}")

    text = unicodedata.normalize("NFKC", raw).strip()
    if text.startswith("#"):
        text = text[1:].strip()
    text = text.lower()

    segments = []
    for part in text.split(HIERARCHY_SEPARATOR):
        part = _WHITESPACE_RUN.sub("-", part.strip())
        if part:
            segments.append(part)

    if not segments:
        raise InvalidTagError(f"tag name is empty after normalization: {raw!r}")

    for segment in segments:
        if not _VALID_SEGMENT.match(segment):
            raise InvalidTagError(
                f"invalid tag segment {segment!r} in {raw!r}; use letters, "
                "digits, '_' or '-', starting with a letter or digit"
            )

    name = HIERARCHY_SEPARATOR.join(segments)
    if len(name) > MAX_TAG_LENGTH:
        raise InvalidTagError(
            f"tag name is longer than {MAX_TAG_LENGTH} characters: {name!r}"
        )
    return name


def parse_tag_list(text: str) -> list[str]:
    """Split a comma-separated string into normalized, unique tag names.

    Blank entries are ignored. The order of first appearance is kept so
    that command output matches what the user typed.
    """
    seen: set[str] = set()
    result: list[str] = []
    for item in text.split(","):
        if not item.strip():
            continue
        name = normalize_tag_name(item)
        if name not in seen:
            seen.add(name)
            result.append(name)
    return result


@dataclass(frozen=True)
class Tag:
    """A tag as stored in the ``tags`` table.

    ``id`` and ``created_at`` are None until the tag has been saved.
    The ``name`` field is always normalized, including for instances
    built directly through the constructor.
    """

    name: str
    id: Optional[int] = None
    created_at: Optional[str] = None

    def __post_init__(self) -> None:
        # The dataclass is frozen, so assign through object.__setattr__.
        object.__setattr__(self, "name", normalize_tag_name(self.name))

    @classmethod
    def from_row(cls, row: sqlite3.Row) -> "Tag":
        """Build a Tag from a row with id, name and created_at columns."""
        return cls(name=row["name"], id=row["id"], created_at=row["created_at"])

    @property
    def segments(self) -> tuple[str, ...]:
        """The hierarchy levels of the name, from top level downward."""
        return tuple(self.name.split(HIERARCHY_SEPARATOR))

    @property
    def parent_name(self) -> Optional[str]:
        """Name of the enclosing tag, or None for a top-level tag."""
        head, sep, _ = self.name.rpartition(HIERARCHY_SEPARATOR)
        return head if sep else None

    def is_descendant_of(self, other: "Tag | str") -> bool:
        """True if this tag is nested anywhere below ``other``."""
        other_name = other.name if isinstance(other, Tag) else normalize_tag_name(other)
        return self.name.startswith(other_name + HIERARCHY_SEPARATOR)

    def __str__(self) -> str:
        return self.name


def unique_tags(names: Iterable[str]) -> list[Tag]:
    """Create Tag objects from raw names, dropping duplicates after normalization."""
    tags: dict[str, Tag] = {}
    for raw in names:
        tag = Tag(raw)
        tags.setdefault(tag.name, tag)
    return list(tags.values())
```

services/export_service.py — Orchestrates exporters and selects notes to export

```python
"""Export orchestration for the notes CLI.

The service decides which notes are exported and which exporter renders
them. Exporters only know how to turn a sequence of notes into bytes or
text on a stream; they never touch the database.
"""

from __future__ import annotations

import logging
import os
import tempfile
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Protocol, Sequence, TextIO

from notes.errors import ExportError, UnknownFormatError
from notes.models import Note
from notes.repository import NoteRepository

logger = logging.getLogger(__name__)


class Exporter(Protocol):
    """Interface every export format must implement."""

    name: str
    extension: str

    def write(self, notes: Sequence[Note], stream: TextIO) -> None:
        """Render the notes onto an open text stream."""


@dataclass(frozen=True)
class ExportSelection:
    """Criteria describing which notes belong in an export.

    An empty selection means "every non-archived note". When note_ids is
    given, it takes precedence and the tag and date filters still apply
    to the notes that were found.
    """

    note_ids: tuple[int, ...] = ()
    tags: tuple[str, ...] = ()
    match_all_tags: bool = False
    created_after: datetime | None = None
    created_before: datetime | None = None
    include_archived: bool = False


@dataclass
class ExportResult:
    """Summary returned to the CLI layer after an export finishes."""

    format_name: str
    note_count: int
    path: Path | None = None
    missing_ids: list[int] = field(default_factory=list)


class ExportService:
    """Selects notes from the repository and hands them to an exporter."""

    def __init__(self, repository: NoteRepository) -> None:
        self._repository = repository
        self._exporters: dict[str, Exporter] = {}

    def register(self, exporter: Exporter) -> None:
        """Make an exporter available under its lowercase name."""
        key = exporter.name.lower()
        if key in self._exporters:
            raise ValueError(f"Exporter already registered: {key}")
        self._exporters[key] = exporter

    def available_formats(self) -> list[str]:
        return sorted(self._exporters)

    def select_notes(self, selection: ExportSelection) -> tuple[list[Note], list[int]]:
        """Return matching notes and any requested ids that do not exist."""
        missing: list[int] = []
        if selection.note_ids:
            notes = list(self._repository.get_many(selection.note_ids))
            found = {note.id for note in notes}
            missing = [i for i in selection.note_ids if i not in found]
        else:
            notes = list(self._repository.list_notes(
                include_archived=selection.include_archived))

        wanted = {tag.strip().lower() for tag in selection.tags if tag.strip()}
        if wanted:
            notes = [n for n in notes if self._tags_match(n, wanted, selection)]
        if selection.created_after is not None:
            notes = [n for n in notes if n.created_at >= selection.created_after]
        if selection.created_before is not None:
            notes = [n for n in notes if n.created_at < selection.created_before]

        notes.sort(key=lambda n: (n.created_at, n.id))
        return notes, missing

    @staticmethod
    def _tags_match(note: Note, wanted: set[str], selection: ExportSelection) -> bool:
        have = {tag.lower() for tag in note.tags}
        if selection.match_all_tags:
            return wanted <= have
        return not wanted.isdisjoint(have)

    def export(self, format_name: str, selection: ExportSelection,
               destination: Path | None = None,
               stdout: TextIO | None = None) -> ExportResult:
        """Run an export to a file, or to stdout when no path is given."""
        exporter = self._exporters.get(format_name.lower())
        if exporter is None:
            raise UnknownFormatError(format_name, self.available_formats())

        notes, missing = self.select_notes(selection)
        if not notes:
            raise ExportError("No notes matched the given selection.")

        if destination is None:
            if stdout is None:
                raise ExportError("Either a destination or a stream is required.")
            exporter.write(notes, stdout)
        else:
            self._write_atomically(exporter, notes, destination)

        logger.info("Exported %d notes as %s", len(notes), exporter.name)
        return ExportResult(exporter.name, len(notes), destination, missing)

    @staticmethod
    def _write_atomically(exporter: Exporter, notes: Sequence[Note],
                          destination: Path) -> None:
        """Write to a temporary file, then replace the destination.

        This keeps an existing file intact if the exporter fails midway.
        """
        destination.parent.mkdir(parents=True, exist_ok=True)
        fd, temp_name = tempfile.mkstemp(dir=destination.parent, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
                exporter.write(notes, handle)
            os.replace(temp_name, destination)
        except Exception as exc:
            Path(temp_name).unlink(missing_ok=True)
            raise ExportError(f"Could not write {destination}: {exc}") from exc
```

exporters/base.py — Abstract exporter interface and registry

```python
"""Abstract exporter interface and registry for the notes CLI.

Every export format (Markdown, JSON, HTML, ...) is implemented as a
subclass of ``Exporter`` and registered under a short format name with
the ``@register`` decorator. The CLI looks formats up by name through
``get_exporter`` and never imports concrete exporter modules directly.
"""
from __future__ import annotations

import abc
import sys
from pathlib import Path
from typing import Callable, ClassVar, Dict, Iterable, Iterator, List, Optional, TextIO, Type

from notes.models import Note


class ExporterError(Exception):
    """Raised when an export cannot be completed."""


class UnknownFormatError(ExporterError):
    """Raised when a requested format name has no registered exporter."""


class Exporter(abc.ABC):
    """Base class for all exporters.

    Subclasses must define the class attributes ``name`` and ``extension``
    and implement ``render``, which yields the output as text chunks.
    Writing to a file or stream is handled here so that every format
    behaves the same way with respect to encoding and error handling.
    """

    #: Short identifier used on the command line, e.g. "markdown".
    name: ClassVar[str] = ""
    #: Default file extension including the leading dot, e.g. ".md".
    extension: ClassVar[str] = ""
    #: One-line description shown by the "formats" subcommand.
    description: ClassVar[str] = ""

    def __init__(self, **options: object) -> None:
        self.options = dict(options)
        self.validate_options()

    def validate_options(self) -> None:
        """Hook for subclasses to reject unsupported or malformed options."""

    @abc.abstractmethod
    def render(self, notes: Iterable[Note]) -> Iterator[str]:
        """Yield the serialized form of ``notes`` as text chunks.

        Implementations should consume ``notes`` lazily so that large
        databases can be exported without loading every row into memory.
        """

    def export(self, notes: Iterable[Note], dest: Optional[Path] = None) -> int:
        """Write the rendered notes to ``dest`` or to standard output.

        Returns the number of chunks written. A destination of ``None``
        or ``Path("-")`` selects standard output.
        """
        if dest is None or str(dest) == "-":
            return self._write(notes, sys.stdout)

        target = Path(dest)
        if target.suffix == "":
            target = target.with_suffix(self.extension)
        try:
            with target.open("w", encoding="utf-8", newline="\n") as handle:
                return self._write(notes, handle)
        except OSError as exc:
            raise ExporterError(f"cannot write {target}: {exc.strerror}") from exc

    def _write(self, notes: Iterable[Note], stream: TextIO) -> int:
        count = 0
        for chunk in self.render(notes):
            stream.write(chunk)
            count += 1
        stream.flush()
        return count


_REGISTRY: Dict[str, Type[Exporter]] = {}


def register(cls: Type[Exporter]) -> Type[Exporter]:
    """Class decorator that adds an exporter to the registry.

    The class must be a concrete ``Exporter`` subclass with a non-empty
    ``name``. Registering two classes under the same name is an error.
    """
    if not (isinstance(cls, type) and issubclass(cls, Exporter)):
        raise TypeError(f"{cls!r} is not an Exporter subclass")
    if not cls.name:
        raise ValueError(f"{cls.__name__} must define a non-empty 'name'")
    if not cls.extension.startswith("."):
        raise ValueError(f"{cls.__name__}.extension must start with a dot")
    if cls.name in _REGISTRY:
        existing = _REGISTRY[cls.name].__name__
        raise ValueError(f"format {cls.name!r} is already registered by {existing}")
    _REGISTRY[cls.name] = cls
    return cls


def get_exporter(name: str, **options: object) -> Exporter:
    """Instantiate the exporter registered as ``name``."""
    try:
        cls = _REGISTRY[name.lower()]
    except KeyError:
        known = ", ".join(available_formats()) or "none"
        raise UnknownFormatError(
            f"unknown export format {name!r} (available: {known})"
        ) from None
    return cls(**options)


def available_formats() -> List[str]:
    """Return the registered format names in alphabetical order."""
    return sorted(_REGISTRY)


def describe_formats() -> Iterator[Callable[[], str]]:
    """Yield callables that each produce one line of the formats listing."""
    for format_name in available_formats():
        cls = _REGISTRY[format_name]
        yield lambda cls=cls: f"{cls.name:<10} {cls.extension:<6} {cls.description}"
```

importers/markdown_importer.py — Parses Markdown files with front matter into notes

"""Import Markdown files with optional front matter into the notes database.

A file may begin with a block delimited by lines containing only '---'.
Inside the block, simple 'key: value' pairs are supported, along with
inline lists ('tags: [a, b]') and dash lists:

    tags:
      - python
      - sqlite

Recognised keys are 'title', 'tags' and 'created'. Unknown keys are ignored.
If no title is given, the first level-one heading or the file name is used.
"""
from __future__ import annotations

import re
import sqlite3
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path

FRONT_MATTER_RE = re.compile(r"\A---[ \t]*\n(.*?)\n---[ \t]*(?:\n|\Z)", re.DOTALL)
HEADING_RE = re.compile(r"^#\s+(.+?)\s*$", re.MULTILINE)


@dataclass
class ParsedNote:
    """A note read from disk, not yet stored."""
    title: str
    body: str
    tags: list[str] = field(default_factory=list)
    created: str | None = None
    source_path: str = ""


@dataclass
class ImportResult:
    """Counts reported back to the command-line layer."""
    imported: int = 0
    skipped: int = 0
    failed: int = 0


def _parse_value(raw: str) -> str | list[str]:
    """Convert a raw value into a string, or a list for inline lists."""
    raw = raw.strip()
    if raw.startswith("[") and raw.endswith("]"):
        return [item.strip().strip("'\"") for item in raw[1:-1].split(",") if item.strip()]
    return raw.strip("'\"")


def parse_front_matter(text: str) -> tuple[dict, str]:
    """Split text into a metadata dict and the remaining body."""
    match = FRONT_MATTER_RE.match(text)
    if not match:
        return {}, text

    meta: dict = {}
    current_key = None
    for line in match.group(1).splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        stripped = line.strip()
        if stripped.startswith("- ") and current_key is not None:
            # Continuation of a dash list under the previous key.
            if not isinstance(meta.get(current_key), list):
                meta[current_key] = []
            meta[current_key].append(stripped[2:].strip().strip("'\""))
        elif ":" in line:
            key, _, value = line.partition(":")
            current_key = key.strip().lower()
            meta[current_key] = _parse_value(value) if value.strip() else []
    return meta, text[match.end():]


def _normalise_tags(value) -> list[str]:
    """Return lowercase, de-duplicated tags in their original order."""
    if isinstance(value, str):
        value = [part for part in re.split(r"[,\s]+", value) if part]
    seen: dict[str, None] = {}
    for tag in value or []:
        cleaned = tag.strip().lstrip("#").lower()
        if cleaned:
            seen[cleaned] = None
    return list(seen)


def _normalise_date(value) -> str | None:
    """Return an ISO 8601 string, or None if the value cannot be read."""
    if not isinstance(value, str) or not value:
        return None
    try:
        return datetime.fromisoformat(value).isoformat(timespec="seconds")
    except ValueError:
        return None


def parse_file(path: Path) -> ParsedNote:
    """Read one Markdown file and build a ParsedNote."""
    text = path.read_text(encoding="utf-8")
    meta, body = parse_front_matter(text)
    body = body.strip()

    title = meta.get("title")
    if not isinstance(title, str) or not title:
        heading = HEADING_RE.search(body)
        title = heading.group(1) if heading else path.stem

    created = _normalise_date(meta.get("created"))
    if created is None:
        # Fall back to the file's modification time.
        created = datetime.fromtimestamp(path.stat().st_mtime).isoformat(timespec="seconds")

    return ParsedNote(
        title=title,
        body=body,
        tags=_normalise_tags(meta.get("tags")),
        created=created,
        source_path=str(path.resolve()),
    )


def import_directory(conn: sqlite3.Connection, directory: Path,
                     recursive: bool = True) -> ImportResult:
    """Import every .md file under directory.

    Files whose absolute path is already recorded in notes.source_path are
    skipped, so running the importer repeatedly is safe. Each file is stored
    in its own transaction so one bad file does not block the others.
    """
    result = ImportResult()
    pattern = "**/*.md" if recursive else "*.md"
    for path in sorted(directory.glob(pattern)):
        try:
            note = parse_file(path)
            exists = conn.execute(
                "SELECT 1 FROM notes WHERE source_path = ?", (note.source_path,)
            ).fetchone()
            if exists:
                result.skipped += 1
                continue
            with conn:
                cur = conn.execute(
                    "INSERT INTO notes (title, body, created_at, source_path) "
                    "VALUES (?, ?, ?, ?)",
                    (note.title, note.body, note.created, note.source_path),
                )
                conn.executemany(
                    "INSERT OR IGNORE INTO note_tags (note_id, tag) VALUES (?, ?)",
                    [(cur.lastrowid, tag) for tag in note.tags],
                )
            result.imported += 1
        except (OSError, UnicodeDecodeError, sqlite3.Error):
            result.failed += 1
    return result

config/settings.py — Loads, validates, and merges config from file and environment

"""Configuration loading for the notes command-line tool.

Settings come from four layers, applied in this order (later wins):

    1. built-in defaults
    2. a TOML file (path from --config, NOTES_CONFIG, or the default location)
    3. environment variables prefixed with NOTES_
    4. explicit overrides, typically parsed from command-line flags
"""
from __future__ import annotations

import os
import tomllib
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Mapping

ENV_PREFIX = "NOTES_"
CONFIG_ENV_VAR = "NOTES_CONFIG"
DEFAULT_CONFIG_PATH = Path.home() / ".config" / "notes" / "config.toml"
VALID_EXPORT_FORMATS = ("json", "markdown", "csv")


class ConfigError(Exception):
    """Raised when configuration cannot be read or contains invalid values."""


@dataclass(frozen=True)
class Settings:
    """Resolved, validated configuration for a single run of the tool."""

    db_path: Path
    export_format: str = "markdown"
    editor: str = ""
    search_limit: int = 50
    color: bool = True


# The expected type of each setting. This table drives coercion, so a new
# setting only needs an entry here, a default below, and a Settings field.
_FIELD_TYPES: dict[str, type] = {
    "db_path": Path,
    "export_format": str,
    "editor": str,
    "search_limit": int,
    "color": bool,
}

_DEFAULTS: dict[str, Any] = {
    "db_path": Path.home() / ".local" / "share" / "notes" / "notes.db",
    "export_format": "markdown",
    "editor": "",
    "search_limit": 50,
    "color": True,
}


def _parse_bool(name: str, raw: str) -> bool:
    """Interpret common textual spellings of a boolean."""
    lowered = raw.strip().lower()
    if lowered in {"1", "true", "yes", "on"}:
        return True
    if lowered in {"0", "false", "no", "off"}:
        return False
    raise ConfigError(f"{name}: cannot interpret {raw!r} as a boolean")


def _coerce(name: str, value: Any) -> Any:
    """Convert a raw value from any source into the type the field expects."""
    kind = _FIELD_TYPES[name]
    if kind is bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return _parse_bool(name, value)
        raise ConfigError(f"{name}: expected a boolean, got {value!r}")
    if kind is int:
        if isinstance(value, bool):
            raise ConfigError(f"{name}: expected an integer, got {value!r}")
        try:
            return int(value)
        except (TypeError, ValueError):
            raise ConfigError(f"{name}: expected an integer, got {value!r}") from None
    if kind is Path:
        return Path(str(value)).expanduser()
    return str(value)


def read_file(path: Path) -> dict[str, Any]:
    """Read settings from a TOML file. A missing file yields no values."""
    if not path.is_file():
        return {}
    try:
        with path.open("rb") as handle:
            data = tomllib.load(handle)
    except tomllib.TOMLDecodeError as exc:
        raise ConfigError(f"{path}: invalid TOML ({exc})") from exc
    unknown = sorted(set(data) - set(_FIELD_TYPES))
    if unknown:
        raise ConfigError(f"{path}: unknown setting(s): {', '.join(unknown)}")
    return dict(data)


def read_env(environ: Mapping[str, str]) -> dict[str, Any]:
    """Collect settings from NOTES_* variables, e.g. NOTES_SEARCH_LIMIT."""
    found: dict[str, Any] = {}
    for name in _FIELD_TYPES:
        key = ENV_PREFIX + name.upper()
        if key in environ:
            found[name] = environ[key]
    return found


def merge(*layers: Mapping[str, Any]) -> dict[str, Any]:
    """Combine layers left to right, coercing every value as it is applied."""
    merged: dict[str, Any] = {}
    for layer in layers:
        for name, value in layer.items():
            if value is None:
                continue  # an unset command-line flag must not erase a value
            merged[name] = _coerce(name, value)
    return merged


def validate(values: Mapping[str, Any]) -> Settings:
    """Check value constraints and build the final Settings object."""
    if values["export_format"] not in VALID_EXPORT_FORMATS:
        allowed = ", ".join(VALID_EXPORT_FORMATS)
        raise ConfigError(f"export_format must be one of: {allowed}")
    if values["search_limit"] < 1:
        raise ConfigError("search_limit must be a positive integer")
    return Settings(**values)


def load_settings(
    config_path: Path | None = None,
    environ: Mapping[str, str] | None = None,
    overrides: Mapping[str, Any] | None = None,
) -> Settings:
    """Resolve settings from defaults, file, environment, and overrides."""
    environ = os.environ if environ is None else environ
    if config_path is None:
        config_path = Path(environ.get(CONFIG_ENV_VAR, DEFAULT_CONFIG_PATH))
    config_path = config_path.expanduser()

    merged = merge(
        _DEFAULTS,
        read_file(config_path),
        read_env(environ),
        overrides or {},
    )
    return validate(merged)

