```python
"""Custom exceptions and exit code mapping for the notes CLI.

Every error the tool raises on purpose derives from NotesError. Each
subclass carries an exit code so that shell scripts can distinguish
failure modes without parsing messages. Unexpected exceptions are not
caught here; they fall through to the generic handler in run_cli().
"""
from __future__ import annotations

import sqlite3
import sys
from typing import Callable, Optional

# Exit codes. Values are fixed because scripts may depend on them.
EXIT_OK = 0
EXIT_GENERAL = 1
EXIT_USAGE = 2
EXIT_NOT_FOUND = 3
EXIT_VALIDATION = 4
EXIT_DATABASE = 5
EXIT_CONFLICT = 6
EXIT_EXPORT = 7
EXIT_INTERRUPTED = 130


class NotesError(Exception):
    """Base class for all expected errors raised by the tool."""

    exit_code = EXIT_GENERAL

    def __init__(self, message: str, hint: Optional[str] = None) -> None:
        super().__init__(message)
        self.message = message
        self.hint = hint

    def __str__(self) -> str:
        return self.message


class NotFoundError(NotesError):
    """A requested record does not exist."""

    exit_code = EXIT_NOT_FOUND


class NoteNotFoundError(NotFoundError):
    def __init__(self, note_id: int) -> None:
        super().__init__(
            f"No note with id {note_id}.",
            hint="Run 'notes list' to see available ids.",
        )
        self.note_id = note_id


class TagNotFoundError(NotFoundError):
    def __init__(self, tag: str) -> None:
        super().__init__(f"No tag named '{tag}'.")
        self.tag = tag


class ValidationError(NotesError):
    """User-supplied input was rejected before touching the database."""

    exit_code = EXIT_VALIDATION


class EmptyNoteError(ValidationError):
    def __init__(self) -> None:
        super().__init__(
            "A note must contain some text.",
            hint="Pass text as an argument or pipe it on standard input.",
        )


class InvalidTagError(ValidationError):
    def __init__(self, tag: str, reason: str) -> None:
        super().__init__(f"Invalid tag '{tag}': {reason}")
        self.tag = tag


class ConflictError(NotesError):
    """The requested change collides with existing data."""

    exit_code = EXIT_CONFLICT


class DuplicateTagError(ConflictError):
    def __init__(self, note_id: int, tag: str) -> None:
        super().__init__(f"Note {note_id} already has the tag '{tag}'.")


class DatabaseError(NotesError):
    """The SQLite layer failed or the database is unusable."""

    exit_code = EXIT_DATABASE


class DatabaseLockedError(DatabaseError):
    def __init__(self, path: str) -> None:
        super().__init__(
            f"The database at {path} is locked by another process.",
            hint="Close other notes sessions and try again.",
        )


class SchemaVersionError(DatabaseError):
    def __init__(self, found: int, expected: int) -> None:
        super().__init__(
            f"Database schema version is {found}; this tool expects {expected}.",
            hint="Run 'notes migrate' to bring the database up to date.",
        )


class ExportError(NotesError):
    """Writing an export file failed or the format is not supported."""

    exit_code = EXIT_EXPORT


class UnsupportedFormatError(ExportError):
    def __init__(self, fmt: str, supported: list[str]) -> None:
        names = ", ".join(sorted(supported))
        super().__init__(
            f"Unsupported export format '{fmt}'.",
            hint=f"Supported formats: {names}.",
        )


def from_sqlite(exc: sqlite3.Error, path: str) -> DatabaseError:
    """Translate a sqlite3 exception into the matching DatabaseError."""
    text = str(exc).lower()
    if "locked" in text or "busy" in text:
        return DatabaseLockedError(path)
    return DatabaseError(f"SQLite error: {exc}")


def exit_code_for(exc: BaseException) -> int:
    """Return the process exit code that corresponds to an exception."""
    if isinstance(exc, NotesError):
        return exc.exit_code
    if isinstance(exc, KeyboardInterrupt):
        return EXIT_INTERRUPTED
    return EXIT_GENERAL


def format_error(exc: NotesError) -> str:
    """Build the text shown to the user on standard error."""
    lines = [f"error: {exc.message}"]
    if exc.hint:
        lines.append(f"hint: {exc.hint}")
    return "\n".join(lines)


def run_cli(main: Callable[[], int], db_path: str) -> int:
    """Run the entry point and convert exceptions into exit codes."""
    try:
        return main()
    except NotesError as exc:
        print(format_error(exc), file=sys.stderr)
        return exit_code_for(exc)
    except sqlite3.Error as exc:
        wrapped = from_sqlite(exc, db_path)
        print(format_error(wrapped), file=sys.stderr)
        return exit_code_for(wrapped)
    except KeyboardInterrupt:
        print("Interrupted.", file=sys.stderr)
        return EXIT_INTERRUPTED
