"""Tests for search ranking, filters, and export formats.

These tests run against an in-memory SQLite database populated by the
`populated` fixture, so no files are written except by the export tests,
which use pytest's tmp_path.
"""

import csv
import json

import pytest

from notes import db, export, search
from notes.core import add_note, tag_note


@pytest.fixture
def conn():
    """Provide a fresh in-memory database with the schema applied."""
    connection = db.connect(":memory:")
    db.init_schema(connection)
    yield connection
    connection.close()


@pytest.fixture
def populated(conn):
    """Insert a small, fixed set of notes with known tags and dates."""
    add_note(conn, title="Grocery list", body="milk eggs bread",
             created="2024-01-05")
    add_note(conn, title="Python tips",
             body="Use pathlib. pathlib makes paths easy. Prefer pathlib.",
             created="2024-02-10")
    add_note(conn, title="Meeting notes",
             body="Discuss pathlib migration and release plan",
             created="2024-03-15")
    add_note(conn, title="Release checklist", body="tag, build, publish",
             created="2024-03-20")
    tag_note(conn, 2, "python")
    tag_note(conn, 3, "work")
    tag_note(conn, 4, "work")
    tag_note(conn, 4, "release")
    return conn


# ---------------------------------------------------------------- ranking

def test_search_returns_only_matching_notes(populated):
    results = search.search_notes(populated, "pathlib")
    titles = {r.title for r in results}
    assert titles == {"Python tips", "Meeting notes"}


def test_more_frequent_term_ranks_higher(populated):
    results = search.search_notes(populated, "pathlib")
    assert results[0].title == "Python tips"


def test_title_match_outranks_body_match(populated):
    results = search.search_notes(populated, "release")
    # "Release checklist" has the term in its title, while "Meeting notes"
    # only mentions it in the body.
    assert results[0].title == "Release checklist"
    assert results[1].title == "Meeting notes"


def test_search_is_case_insensitive(populated):
    lower = search.search_notes(populated, "python")
    upper = search.search_notes(populated, "PYTHON")
    assert [r.id for r in lower] == [r.id for r in upper]


def test_no_match_returns_empty_list(populated):
    assert search.search_notes(populated, "nonexistent") == []


# ---------------------------------------------------------------- filters

def test_filter_by_single_tag(populated):
    results = search.search_notes(populated, "release", tags=["work"])
    assert {r.title for r in results} == {"Meeting notes", "Release checklist"}


def test_filter_by_multiple_tags_requires_all(populated):
    results = search.search_notes(populated, "release",
                                 tags=["work", "release"])
    assert [r.title for r in results] == ["Release checklist"]


def test_filter_by_date_range_is_inclusive(populated):
    results = search.search_notes(
        populated, "", since="2024-02-10", until="2024-03-15"
    )
    assert {r.title for r in results} == {"Python tips", "Meeting notes"}


def test_limit_truncates_results(populated):
    results = search.search_notes(populated, "", limit=2)
    assert len(results) == 2


def test_invalid_date_raises_value_error(populated):
    with pytest.raises(ValueError):
        search.search_notes(populated, "", since="not-a-date")


# ----------------------------------------------------------------- export

def test_export_json_round_trips(populated, tmp_path):
    target = tmp_path / "notes.json"
    export.export_notes(populated, target, fmt="json")
    data = json.loads(target.read_text(encoding="utf-8"))
    assert len(data) == 4
    by_title = {item["title"]: item for item in data}
    assert sorted(by_title["Release checklist"]["tags"]) == ["release", "work"]


def test_export_csv_has_header_and_rows(populated, tmp_path):
    target = tmp_path / "notes.csv"
    export.export_notes(populated, target, fmt="csv")
    with target.open(newline="", encoding="utf-8") as handle:
        rows = list(csv.DictReader(handle))
    assert set(rows[0]) >= {"id", "title", "body", "tags", "created"}
    assert len(rows) == 4


def test_export_markdown_contains_titles_and_tags(populated, tmp_path):
    target = tmp_path / "notes.md"
    export.export_notes(populated, target, fmt="markdown")
    text = target.read_text(encoding="utf-8")
    assert "# Python tips" in text
    assert "Tags: python" in text


def test_export_respects_search_filters(populated, tmp_path):
    target = tmp_path / "work.json"
    export.export_notes(populated, target, fmt="json", tags=["work"])
    data = json.loads(target.read_text(encoding="utf-8"))
    assert {item["title"] for item in data} == {
        "Meeting notes", "Release checklist"
    }


def test_export_unknown_format_is_rejected(populated, tmp_path):
    with pytest.raises(export.UnsupportedFormatError):
        export.export_notes(populated, tmp_path / "x.out", fmt="xml")
